	protected void startTransaction() {
		if (transactionCount++ == 0) {
			transactionID = program.startTransaction("Test Transaction");
		}
	}

	protected void endTransaction() {
		endTransaction(true);
	}

	protected void endTransaction(bool commit) {
		if (--transactionCount == 0) {
			program.endTransaction(transactionID, true);
		}
	}

	private static Language getLanguage(string languageId)
    {
		Language language = LANGUAGE_CACHE.get(languageId);
		if (language == null) {
			language =
				DefaultLanguageService.getLanguageService().getLanguage(new LanguageID(languageId));
			LANGUAGE_CACHE.put(languageId, language);
		}
		return language;
	}

