	public void createEncodedString(string address, string string, Charset encoding,
			bool nullTerminate)
    {
		byte[] bytes = string.getBytes(encoding);

		if (encoding == StandardCharsets.US_ASCII || encoding == StandardCharsets.UTF_8) {
			if (nullTerminate) {
				bytes = Arrays.copyOf(bytes, bytes.length + 1);
			}
			setBytes(address, bytes);
			applyDataType(address, new StringDataType(), 1);
		}
		else if (encoding == StandardCharsets.UTF_16BE || encoding == StandardCharsets.UTF_16LE) {
			if (nullTerminate) {
				bytes = Arrays.copyOf(bytes, bytes.length + 2);
				setBytes(address, bytes);
				applyDataType(address, new TerminatedUnicodeDataType(), 1);
			}
			else {
				setBytes(address, bytes);
			}
		}
		else {
			setBytes(address, bytes);
		}
	}

	/**
	 * Creates a non-null-terminated ascii string at the given address 
	 * @param address the address
	 * @param string the string 
	 * @return the new data
	 * @throws Exception if there is an exception
	 */
	public Data createString(string address, string string)
    {
		return createString(address, string, StandardCharsets.US_ASCII, false,
			StringDataType.dataType);
	}

	public Data createString(string address, string string, Charset charset, bool nullTerminate,
			DataType dataType)
    {
		if (nullTerminate) {
			string = string + "\0";
		}
		byte[] bytes = string.getBytes(charset);
		return createString(address, bytes, charset, dataType);
	}

	public Data createString(string address, byte[] stringBytes, Charset charset, DataType dataType)
    {
		Address addr = addr(address);
		setBytes(address, stringBytes);
		if (dataType != null) {
			startTransaction();
			try {
				Data data = DataUtilities.createData(program, addr, dataType, stringBytes.length,
					ClearDataMode.CLEAR_ALL_UNDEFINED_CONFLICT_DATA);
				CharsetSettingsDefinition.CHARSET.setCharset(data, charset.name());
				return data;
			}
			finally {
				endTransaction();
			}
		}
		return null;
	}

