	public void tx<E>/* where E : Exception */(ExceptionalCallback<E> c) {
		startTransaction();
		bool commit = true;
		try {
			c.call();
		}
		catch (Exception e) {
			commit = false;
			throw new AssertException(e);
		}
		finally {
			endTransaction(commit);
		}
	}

	public R tx<R, E>/* where E : Exception */(ExceptionalSupplier<R, E> s) {
		startTransaction();
		bool commit = true;
		try {
			return s.get();
		}
		catch (Exception e) {
			commit = false;
			throw new AssertException(e);
		}
		finally {
			endTransaction(commit);
		}
	}

	public interface ExceptionalSupplier<R, E> where E : Exception {
		public R get();
	}
}
